-- Restore the omitted included allowance only for the legacy repair performed in 0011.
-- Existing funded or used accounts are excluded; a unique ledger key makes this one-time.
INSERT OR IGNORE INTO ledger SELECT 'legacy-allowance:'||s.user_id||':'||s.starts_at,u.id,coalesce(p.credits,CASE s.plan WHEN 'lite' THEN 100 WHEN 'plus' THEN 350 WHEN 'pro' THEN 1000 END),'Кредиты тарифа: восстановление пропущенного пакета','schema-migration',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM subscriptions s JOIN users u ON u.id=s.user_id LEFT JOIN plans p ON p.id=s.plan WHERE s.source='legacy-admin-repair' AND s.plan IN ('lite','plus','pro') AND s.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND s.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND u.status='active' AND u.credits=0 AND NOT EXISTS(SELECT 1 FROM ledger l WHERE l.user_id=u.id AND l.amount>0) AND NOT EXISTS(SELECT 1 FROM requests r WHERE r.user_id=u.id);
--> statement-breakpoint
UPDATE users SET credits=credits+(SELECT l.amount FROM ledger l JOIN subscriptions s ON s.user_id=l.user_id WHERE l.user_id=users.id AND l.id='legacy-allowance:'||s.user_id||':'||s.starts_at) WHERE credits=0 AND status='active' AND NOT EXISTS(SELECT 1 FROM requests r WHERE r.user_id=users.id) AND EXISTS(SELECT 1 FROM ledger l JOIN subscriptions s ON s.user_id=l.user_id WHERE l.user_id=users.id AND l.id='legacy-allowance:'||s.user_id||':'||s.starts_at AND NOT EXISTS(SELECT 1 FROM audit a WHERE a.id=l.id));
--> statement-breakpoint
INSERT OR IGNORE INTO audit SELECT l.id,'schema-migration','billing.allowance.restore',l.user_id,'{"reason":"omitted included allowance on legacy subscription repair"}',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM ledger l WHERE l.id LIKE 'legacy-allowance:%';
